const ProjectDuplicateRequestSchema = z
  .object({
    name: z
      .string()
      .openapi({ description: 'The name of the new project.', example: 'New Project Name' }),
    include: z
      .string()
      .regex(
        /([allocations|forms|members|notes|permissions|task_assignee|task_attachments|task_dates|task_dependencies|task_followers|task_notes|task_projects|task_subtasks|task_tags|task_templates|task_type_default])(,\1)*/,
      )
      .exactOptional()
      .openapi({
        description:
          'A comma-separated list of elements to include when duplicating a project.\nSome elements are automatically included and cannot be excluded,\nwhile others are **optional** and must be explicitly specified in this field.\n\n**Auto-included fields (non-configurable)**\n- Tasks\n- [Project Views](https://asana.com/features/project-management/project-views)\n(i.e., tabs in a project such as List, Board, Dashboard, etc.)\n- [Rules](https://help.asana.com/s/article/rules)\n\n*Note: The Owner of the Rules copied to the new project is the user who performs the API call.\nIf the duplication is performed using a [Service Account](/docs/authentication#/service-account),\nnote that Service Accounts cannot access the UI to modify or pause Rules.\nTo prevent unwanted automation behavior, consider pausing Rules in the source project before duplication —\ntheir active/paused state is preserved in the new project.*\n\n**Optional fields (configurable)**\n- allocations\n- forms\n- members\n- notes\n- permissions\n- task_assignee\n- task_attachments\n- task_dates\n- task_dependencies\n- task_followers\n- task_notes\n- task_projects\n- task_subtasks\n- task_tags\n- task_templates\n- task_type_default',
        example: [
          'allocations,forms,members,notes,permissions,task_assignee,task_attachments,task_dates,task_dependencies,task_followers,task_notes,task_projects,task_subtasks,task_tags,task_templates,task_type_default',
        ],
      }),
    schedule_dates: z
      .object({
        should_skip_weekends: z
          .boolean()
          .exactOptional()
          .openapi({
            description: '**Required**: Determines if the auto-shifted dates should skip weekends.',
            example: true,
          }),
        due_on: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'Sets the last due date in the duplicated project to the given date. The rest of the due dates will be offset by the same amount as the due dates in the original project.',
            example: '2019-05-21',
          }),
        start_on: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'Sets the first start date in the duplicated project to the given date. The rest of the start dates will be offset by the same amount as the start dates in the original project.',
            example: '2019-05-21',
          }),
      })
      .exactOptional()
      .openapi({
        description:
          'A dictionary of options to auto-shift dates. `task_dates` must be included to use this option. Requires `should_skip_weekends` and either `start_on` or `due_on`, but not both.',
        required: [],
      }),
  })
  .openapi({ required: ['name'] })
  .openapi('ProjectDuplicateRequest')

