const FieldsParamsSchema = z
  .preprocess(
    (val) =>
      val === undefined
        ? val
        : (Array.isArray(val) ? val : [val]).flatMap((item) =>
            typeof item === 'string' ? item.split(',') : [item],
          ),
    z.array(z.string()),
  )
  .exactOptional()
  .openapi({
    param: {
      name: 'opt_fields',
      in: 'query',
      description:
        'Defines fields to return.\nSome requests return *compact* representations of objects in order to conserve resources and complete the request more efficiently. Other times requests return more information than you may need. This option allows you to list the exact set of fields that the API should be sure to return for the objects. The field names should be provided as paths, described below.\nThe id of included objects will always be returned, regardless of the field options.\nProperties can include nested fields. To learn more, see the [input/output options guide](/docs/inputoutput-options#selecting-nested-fields).',
      example: ['followers', 'assignee'],
      required: false,
      schema: { type: 'array', items: { type: 'string' } },
      style: 'form',
      explode: false,
    },
  })

const PrettyParamsSchema = z
  .preprocess((val) => (val === '' ? undefined : val), z.stringbool().optional())
  .exactOptional()
  .openapi({
    param: {
      name: 'opt_pretty',
      in: 'query',
      description:
        'Provides “pretty” output.\nProvides the response in a “pretty” format. In the case of JSON this means doing proper line breaking and indentation to make it readable. This will take extra time and increase the response size so it is advisable only to use this during debugging.',
      required: false,
      allowEmptyValue: true,
      schema: { type: 'boolean' },
      style: 'form',
      example: true,
    },
  })

const LimitParamsSchema = z
  .preprocess(
    (val) =>
      typeof val === 'string' &&
      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
        ? Number(val)
        : val,
    z.int().min(1).max(100),
  )
  .exactOptional()
  .openapi({
    param: {
      name: 'limit',
      in: 'query',
      description:
        'Results per page.\nThe number of objects to return per page. The value must be between 1 and 100.',
      example: 50,
      schema: { type: 'integer', minimum: 1, maximum: 100 },
      required: false,
    },
  })

const SearchLimitParamsSchema = z
  .preprocess(
    (val) =>
      typeof val === 'string' &&
      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
        ? Number(val)
        : val,
    z.int().min(1).max(100),
  )
  .exactOptional()
  .openapi({
    param: {
      name: 'limit',
      in: 'query',
      description:
        'Results per search response.\nThe number of objects to return in one search response. The value must be between 1 and 100. Search responses have no `next_page`, so to retrieve further results, sort by `created_at` and repeat the query with a `created_at.before` or `created_at.after` filter that excludes the results you have already seen.',
      example: 50,
      schema: { type: 'integer', minimum: 1, maximum: 100 },
      required: false,
    },
  })

const OffsetParamsSchema = z
  .string()
  .exactOptional()
  .openapi({
    param: {
      name: 'offset',
      in: 'query',
      description:
        'Offset token.\nAn offset to the next page returned by the API. A pagination request will return an offset token, which can be used as an input parameter to the next request. If an offset is not passed in, the API will return the first page of results.\n*Note: You can only pass in an offset that was returned to you via a previously paginated request.*',
      example: 'eyJ0eXAiOJiKV1iQLCJhbGciOiJIUzI1NiJ9',
      schema: { type: 'string' },
      required: false,
    },
  })

