const CompletedSinceParamsSchema = z
  .string()
  .exactOptional()
  .openapi({
    param: {
      name: 'completed_since',
      in: 'query',
      required: false,
      description:
        'Only return tasks that are either incomplete or that have been completed since this time. Accepts a date-time string or the keyword *now*.\n',
      schema: { type: 'string' },
      example: '2012-02-22T02:06:58.158Z',
    },
  })

const StoryResourceSubtypeParamsSchema = z
  .literal('comment_added')
  .exactOptional()
  .openapi({
    param: {
      name: 'resource_subtype',
      in: 'query',
      required: false,
      description:
        'Only return stories of this subtype. Only `comment_added` is supported, which narrows the response to comments and excludes activity such as assignments, due date changes, and project moves. Omit to return the full activity feed.\n',
      schema: { type: 'string', enum: ['comment_added'] },
      example: 'comment_added',
    },
  })

const StorySortAscendingParamsSchema = z
  .stringbool()
  .default(true)
  .exactOptional()
  .openapi({
    param: {
      name: 'sort_ascending',
      in: 'query',
      required: false,
      description:
        "Creation-time order: `true` (the default) is oldest first, `false` is newest first. Pair `false` with `limit` to read only the most recent stories. Ordering is applied across the parent's stories; on a parent with an extremely large activity feed the feed may be truncated before it is ordered, so pair `false` with `created_after` to bound what is considered.\n",
      schema: { type: 'boolean', default: true },
      example: false,
    },
  })

const StoryCreatedAfterParamsSchema = z.iso
  .datetime({ offset: true })
  .exactOptional()
  .openapi({
    param: {
      name: 'created_after',
      in: 'query',
      required: false,
      description:
        'Only return stories created after this time. Applies to every story type; pair it with `resource_subtype=comment_added` to get just the comments added since a given moment.\nThe bound is exclusive but has second granularity: it is truncated to the start of its second before filtering, so any story created within that same second is still returned. A client polling with the `created_at` of the last story it saw should expect to see that story again, and others alongside it, and should de-duplicate on `gid`.\n',
      schema: { type: 'string', format: 'date-time' },
      example: '2012-02-22T02:06:58.158Z',
    },
  })

