export const getAccessRequestsRoute = createRoute({
  method: 'get',
  path: '/access_requests',
  tags: ['Access requests'],
  summary: 'Get access requests',
  description:
    'Returns the pending access requests for a target object or a target object filtered by user.',
  operationId: 'getAccessRequests',
  request: {
    query: z.object({
      target: TargetQueryParamParamsSchema,
      user: UserQueryParamParamsSchema,
      opt_pretty: PrettyParamsSchema,
      opt_fields: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.enum(['approval_status', 'message', 'requester', 'requester.name', 'target'])),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'opt_fields',
            in: 'query',
            description:
              'This endpoint returns a resource which excludes some properties by default. To include those optional properties, set this query parameter to a comma-separated list of the properties you wish to include. Properties can include nested fields. To learn more, see the [input/output options guide](/docs/inputoutput-options#selecting-nested-fields).',
            required: false,
            example: ['approval_status', 'message', 'requester', 'requester.name', 'target'],
            schema: {
              type: 'array',
              items: {
                type: 'string',
                enum: ['approval_status', 'message', 'requester', 'requester.name', 'target'],
              },
            },
            style: 'form',
            explode: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successfully retrieved access requests.',
      content: {
        'application/json': {
          schema: z
            .object({ data: z.array(AccessRequestResponseSchema).exactOptional() })
            .openapi({ required: [] }),
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    402: PaymentRequiredResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    500: InternalServerErrorResponse,
  },
  security: [{ personalAccessToken: [] }, { oauth2: [] }],
})

