export const getWorkspacesWorkspaceGidEventsRoute = createRoute({
  method: 'get',
  path: '/workspaces/{workspace_gid}/events',
  tags: ['Workspaces'],
  summary: 'Get workspace events',
  description:
    'Returns the full record for all events that have occurred since the sync token was created.\nThe response is a list of events and the schema of each event is as described [here](/reference/events).\nAsana limits a single sync token to 1000 events. If more than 1000 events exist for a given domain, `has_more: true` will be returned in the response, indicating that there are more events to pull.',
  operationId: 'getWorkspaceEvents',
  request: {
    params: z.object({ workspace_gid: WorkspacePathGidParamsSchema }),
    query: z.object({
      opt_pretty: PrettyParamsSchema,
      sync: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'sync',
            in: 'query',
            required: false,
            description:
              'A sync token received from the last request, or none on first sync. Events will be returned from the point in time that the sync token was generated.\n*Note: On your first request, omit the sync token. The response will be the same as for an expired sync token, and will include a new valid sync token. If the sync token is too old (which may happen from time to time) the API will return a `412 Precondition Failed` error, and include a fresh sync token in the response.*',
            schema: { type: 'string' },
            example: 'de4774f6915eae04714ca93bb2f5ee81',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successfully retrieved events.',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z.array(EventResponseSchema).exactOptional(),
              sync: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'A sync token to be used with the next call to the /events endpoint.',
                  example: 'de4774f6915eae04714ca93bb2f5ee81',
                }),
              has_more: z
                .boolean()
                .exactOptional()
                .openapi({
                  description: 'Indicates whether there are more events to pull.',
                  example: true,
                }),
            })
            .openapi({
              description:
                'The full record for all events that have occurred since the sync token was created.',
              required: [],
            }),
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    500: InternalServerErrorResponse,
  },
  security: [{ personalAccessToken: [] }, { oauth2: [] }],
})
